use super::*;
use rusqlite::OptionalExtension;
use serde::{Deserialize,Serialize};
use std::collections::BTreeSet;
#[derive(Debug,Serialize)]pub struct SourceHistory{pub stage:String,pub representation_kind:String,pub recorded_ts:i64,pub version:String,pub fingerprint:String,pub explanation:String}
#[derive(Debug,Serialize)]pub struct SourceArtifact{pub kind:String,pub version:String,pub recorded_ts:Option<i64>,pub explanation:String}
#[derive(Debug,Serialize)]pub struct SourceVersion{pub item_id:String,pub title:String,pub captured_ts:i64,pub fingerprint:String,pub basis:String}
#[derive(Debug,Serialize)]pub struct SourceIntelligence{
 pub item_id:String,pub title:String,pub source_url:Option<String>,pub capture_method:String,pub captured_ts:i64,pub author:Option<String>,pub language:Option<String>,pub extraction_confidence:f32,pub original_sha256:Option<String>,pub stored_content_fingerprint:String,pub current_representation_fingerprint:String,pub timestamps:Vec<KnowledgeTime>,pub history:Vec<SourceHistory>,pub artifacts:Vec<SourceArtifact>,pub annotations:Vec<refract_core::Annotation>,pub decision_ids:Vec<String>,pub versions:Vec<SourceVersion>,pub limitations:Vec<String>,
}
#[derive(Debug,Deserialize)]#[serde(deny_unknown_fields)]pub struct SourceDiffRequest{pub before_id:String,pub after_id:String}
#[derive(Debug,Serialize)]pub struct SourceDiff{pub before_id:String,pub after_id:String,pub same_saved_url:bool,pub same_recorded_content_fingerprint:bool,pub removed:Vec<KnowledgeExcerpt>,pub added:Vec<KnowledgeExcerpt>,pub limited:bool,pub explanation:String}
impl Store{
 pub fn knowledge_record_snapshot(&self,id:&str)->RefractResult<()>{
  let item=self.knowledge_item(id)?;let original:Option<String>=self.conn.query_row("SELECT sha256 FROM blobs WHERE item_id=?1 AND kind='original' ORDER BY id LIMIT 1",params![id],|r|r.get(0)).optional().map_err(err)?;
  let tx=self.conn.unchecked_transaction().map_err(err)?;
  for(stage,kind,hash,explanation)in[("retained_original","original_bytes_reference",original.unwrap_or_default(),"Snapshot of a recorded original-blob hash; not an authenticity check or reconstruction of past processing"),("retained_representation","extracted_normalized_blocks",fingerprint(&item)?,"Snapshot of current stored compiler blocks; intermediate extraction transformations are not reconstructed")]{
   if !hash.is_empty(){tx.execute("INSERT OR IGNORE INTO source_history (item_id,stage,representation_kind,recorded_ts,version,fingerprint,explanation) VALUES (?1,?2,?3,?4,'retained-state-v1',?5,?6)",params![id,stage,kind,now()?,hash,explanation]).map_err(err)?;}
  }tx.commit().map_err(err)
 }
 pub fn source_intelligence(&self,id:&str)->RefractResult<SourceIntelligence>{
  let item=self.knowledge_item(id)?;let representation=fingerprint(&item)?;let original=self.conn.query_row("SELECT sha256 FROM blobs WHERE item_id=?1 AND kind='original' ORDER BY id LIMIT 1",params![id],|r|r.get(0)).optional().map_err(err)?;
  let mut stmt=self.conn.prepare("SELECT stage,representation_kind,recorded_ts,version,fingerprint,explanation FROM source_history WHERE item_id=?1 ORDER BY id LIMIT 200").map_err(err)?;let history=stmt.query_map(params![id],|r|Ok(SourceHistory{stage:r.get(0)?,representation_kind:r.get(1)?,recorded_ts:r.get(2)?,version:r.get(3)?,fingerprint:r.get(4)?,explanation:r.get(5)?})).map_err(err)?.collect::<Result<Vec<_>,_>>().map_err(err)?;drop(stmt);
  let mut stmt=self.conn.prepare("SELECT kind,ts,note FROM item_times WHERE item_id=?1 ORDER BY ts,id LIMIT 100").map_err(err)?;let timestamps=stmt.query_map(params![id],|r|Ok(KnowledgeTime{item_id:id.into(),kind:r.get(0)?,ts:r.get(1)?,note:r.get(2)?})).map_err(err)?.collect::<Result<Vec<_>,_>>().map_err(err)?;drop(stmt);
  let mut artifacts=Vec::new();
  let scan:Option<(String,i64)>=self.conn.query_row("SELECT extractor_version,scanned_ts FROM consumer_scans WHERE item_id=?1",params![id],|r|Ok((r.get(0)?,r.get(1)?))).optional().map_err(err)?;if let Some((version,ts))=scan{artifacts.push(SourceArtifact{kind:"derived_consumer_candidates".into(),version,recorded_ts:Some(ts),explanation:"Rule-derived structured candidates; per-claim evidence/review is available in Consumer X-Ray".into()});}
  let encoder:Option<String>=self.conn.query_row("SELECT encoder FROM recall_vectors WHERE item_id=?1 LIMIT 1",params![id],|r|r.get(0)).optional().map_err(err)?;if let Some(version)=encoder{artifacts.push(SourceArtifact{kind:"derived_retrieval_vectors".into(),version,recorded_ts:None,explanation:"A local search representation, not source content or a publisher quality score; generation time was not recorded".into()});}
  let mut stmt=self.conn.prepare("SELECT decision_id FROM decision_sources WHERE item_id=?1 ORDER BY decision_id LIMIT 100").map_err(err)?;let decision_ids=stmt.query_map(params![id],|r|r.get(0)).map_err(err)?.collect::<Result<Vec<_>,_>>().map_err(err)?;drop(stmt);
  let mut versions=Vec::new();if let Some(url)=item.source_url.as_deref().filter(|u|!u.is_empty()){
   let mut stmt=self.conn.prepare("SELECT id,COALESCE(title,id),import_ts,content_hash FROM items WHERE source_url=?1 AND id!=?2 AND sense_decision!='ignore' ORDER BY import_ts,id LIMIT 50").map_err(err)?;versions=stmt.query_map(params![url,id],|r|Ok(SourceVersion{item_id:r.get(0)?,title:r.get(1)?,captured_ts:r.get(2)?,fingerprint:r.get(3)?,basis:"Exact same recorded source URL; not proof of common authorship or applicability".into()})).map_err(err)?.collect::<Result<Vec<_>,_>>().map_err(err)?;
  }
  for link in self.list_relationships(Some(id),100)?{if ["earlier_version","follow_up"].contains(&link.kind.as_str()){let other=if link.source_item_id==id{link.target_item_id}else{link.source_item_id};if !versions.iter().any(|v|v.item_id==other)&&self.knowledge_eligible(&other)?{let v=self.knowledge_item(&other)?;versions.push(SourceVersion{item_id:other,title:v.title.unwrap_or_else(||"Version candidate".into()),captured_ts:v.import_ts,fingerprint:v.content_hash,basis:format!("Stored version/follow-up link (suggestion or user assertion): {}",link.basis)});}}}
  Ok(SourceIntelligence{item_id:id.into(),title:item.title.unwrap_or_else(||"Untitled source".into()),source_url:item.source_url,capture_method:item.source_type.as_str().into(),captured_ts:item.import_ts,author:item.author,language:item.language,extraction_confidence:item.extraction_confidence,original_sha256:original,stored_content_fingerprint:item.content_hash,current_representation_fingerprint:representation,timestamps,history,artifacts,annotations:self.list_annotations(id)?.into_iter().take(100).collect(),decision_ids,versions,limitations:vec!["Source history shows recorded retained-state snapshots and known derived artifacts, not an invented complete extraction/transformation history. Legacy processing details may be unavailable.".into(),"Original bytes, extracted/normalized compiler blocks, user annotations/decisions and derived representations are distinct. Intermediate raw extraction is not separately archived. No neural-AI-generated source representation is recorded here.".into(),"Extraction confidence is a heuristic about parsing, not publisher reliability. Hashes/fingerprints do not authenticate a publisher, prove authorship or verify factual claims.".into(),"Version comparison is between separately archived local sources. No webpage is fetched, monitored or overwritten. Dates retain their explicit kinds; no publication date is guessed.".into()]})
 }
 pub fn source_diff(&self,q:&SourceDiffRequest)->RefractResult<SourceDiff>{
  if q.before_id==q.after_id{return Err(RefractError::invalid("select two distinct archived sources"));}let before=self.knowledge_item(&q.before_id)?;let after=self.knowledge_item(&q.after_id)?;
  let a=before.blocks.iter().flat_map(|b|b.text.lines()).collect::<BTreeSet<_>>();let b=after.blocks.iter().flat_map(|b|b.text.lines()).collect::<BTreeSet<_>>();let mut removed=Vec::new();let mut added=Vec::new();let mut limited=false;
  for(item,other,output)in[(&before,&b,&mut removed),(&after,&a,&mut added)]{for block in &item.blocks{for line in block.text.lines().filter(|l|!l.trim().is_empty()&&!other.contains(l)){if output.len()>=200{limited=true;break;}if line.chars().count()>600{limited=true;}output.push(KnowledgeExcerpt{item_id:item.id.clone(),title:item.title.clone().unwrap_or_else(||"Archived source".into()),block_idx:block.idx,quote:line.chars().take(600).collect(),kind:"archived_line_excerpt".into()});}}}
  Ok(SourceDiff{before_id:before.id,after_id:after.id,same_saved_url:before.source_url.is_some()&&before.source_url==after.source_url,same_recorded_content_fingerprint:before.content_hash==after.content_hash,removed,added,limited,explanation:"Exact line-presence comparison of stored parsed blocks, not a semantic/legal judgment or a live webpage diff. Reordering and duplicate-count changes are not detected. Up to 200 line excerpts per side (600 characters each). Both archived originals remain unchanged; matching fingerprints do not authenticate authorship.".into()})
 }
}
